package com.madhukar.upisplitter.controller;
import com.madhukar.upisplitter.dto.*; import com.madhukar.upisplitter.service.AnalyticsService; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController {private final AnalyticsService s;public AnalyticsController(AnalyticsService s){this.s=s;}@GetMapping("/summary") public ApiDtos.ApiResponse<ApiDtos.Summary> summary(Authentication a){return ApiResponseFactory.ok("Analytics summary",s.summary((String)a.getDetails()));}@GetMapping("/status") public ApiDtos.ApiResponse<List<ApiDtos.StatusCount>> status(Authentication a){return ApiResponseFactory.ok("Status analytics",s.status((String)a.getDetails()));}@GetMapping("/daily") public ApiDtos.ApiResponse<List<ApiDtos.DailyCount>> daily(Authentication a){return ApiResponseFactory.ok("Daily analytics",s.daily((String)a.getDetails()));}@GetMapping("/amounts") public ApiDtos.ApiResponse<List<ApiDtos.AmountCount>> amounts(Authentication a){return ApiResponseFactory.ok("Amount distribution",s.amounts((String)a.getDetails()));}}
